12	// ---- Intercept -------------------------------------------------------------------------------
13	
14	// handleUI2Intercept serves GET /ui2/intercept: the interception state and the held queue.
15	func (s *Server) handleUI2Intercept(w http.ResponseWriter, r *http.Request) {
16		ui2Fragment(w, r, "burpsy /ui2/ — Intercept", "intercept", ui2Exec("intercept.html", s.ui2InterceptView()))
17	}
18	
19	// ui2InterceptView builds the intercept page's view model: the held queue plus both rule
20	// lists, so the page renders the rule toggles next to the queue. The rule lists come through
21	// the API like everything else on the page; a list that fails to decode is simply left out of
22	// the view rather than failing the whole page.
23	func (s *Server) ui2InterceptView() map[string]any {
24		rec := newRecorder()
25		s.handleIntercept(rec, newReq(http.MethodGet, "/api/intercept"))
26		var view map[string]any
27		_ = ui2DecodeJSON(rec.Body.Bytes(), &view)
28		s.ui2MarkHeldEditable(view)
29		for _, dir := range []string{"requests", "responses", "websocket_to_server", "websocket_to_client"} {
30			recRules := newRecorder()
31			s.mux.ServeHTTP(recRules, newReq(http.MethodGet, "/api/intercept/rules/"+dir))
32			var state interceptListState
33			if err := ui2DecodeJSON(recRules.Body.Bytes(), &state); err != nil {
34				continue
35			}
36			view["rules_"+dir] = map[string]any{
37				"active":        state.Active,
38				"unconditional": state.Unconditional,
39				"count":         state.Count,
40			}
41		}
42		s.ui2InterceptViewExtras(view)
43		return view
44	}
45	
46	// handleUI2InterceptAction serves POST /ui2/intercept/{action}: enable/disable, forward-all,
47	// drop-all, and the per-item forward-<id>/drop-<id> — local state changes that then refresh the
48	// queue fragment. A forward-<id> whose form carries the editor's raw field forwards the held
49	// message with the operator's edits; without the field the message goes out untouched.
50	func (s *Server) handleUI2InterceptAction(w http.ResponseWriter, r *http.Request) {
51		action := r.PathValue("action")
52		if strings.HasPrefix(action, "rules-") {
53			s.handleUI2InterceptRulesToggle(w, action)
54			return
55		}
56		if s.ui2InterceptOptionAction(w, r, action) {
57			return
58		}
59		var target string
60		body := `{"enabled":true}`
61		switch action {
62		case "enable":
63			target = "/api/intercept/enable"
64		case "disable":
65			target = "/api/intercept/enable"
66			body = `{"enabled":false}`
67		case "forward-all":
68			target = "/api/intercept/forward-all"
69		case "drop-all":
70			target = "/api/intercept/drop-all"
71		default:
72			// The per-item actions ride the same {action} route: forward-<id> resolves the held
73			// message through the API's plain-raw path (the same edit the console sends), drop-<id>
74			// drops it. The id belongs to the held queue, not to any URL of burpsy's own, so a
75			// malformed one is the same kind of caller error as an unknown action name.
76			if idText, ok := strings.CutPrefix(action, "forward-"); ok {
77				id, err := strconv.ParseUint(idText, 10, 64)
78				if err != nil {
79					http.Error(w, "unknown intercept action", http.StatusBadRequest)
80					return
81				}
82				if err := r.ParseForm(); err != nil {
83					http.Error(w, "invalid form body", http.StatusBadRequest)
84					return
85				}
86				fwd := map[string]any{"fix_content_length": r.PostForm.Get("fix_content_length") == "on"}
87				// The editor's textarea always submits a raw field; its presence, not its content,
88				// marks the message as edited and hands the API the operator's bytes instead of the
89				// original. An emptied textarea is a real edit to an empty message, not a missing
90				// field. What the field cannot carry faithfully is line endings — an HTML textarea
91				// normalizes every break in its value to a lone LF — so the submission goes through
92				// ui2EditedRaw before it is treated as bytes for the wire.
93				if rawValues, present := r.PostForm["raw"]; present {
94					submitted := rawValues[len(rawValues)-1]
95					orig, ws, found := s.ui2HeldInfo(id)
96					if found && !ui2TextareaSafe([]byte(orig)) {
97						// The editor is withheld for holds it cannot carry; a raw field arriving
98						// anyway crossed a textarea and came back with replacement characters
99						// where the bytes were (invalid UTF-8 or NUL both get U+FFFD). Refuse by
100						// name rather than ship the corruption — the untouched Forward button
101						// and the console's base64 editor both remain.
102						http.Error(w, "held message is not safe for the page editor (non-UTF-8 or NUL bytes): forward it untouched, or edit the exact bytes in the console's base64 editor", http.StatusBadRequest)
103						return
104					}
105					if found && ui2NormalizeNewlines(orig) == submitted {
106						// An editor round-trip the operator did not change: ship the original
107						// bytes, unmarked — no raw override.
108					} else if ws {
109						// A WebSocket message has no headers: the operator saw and edited the
110						// whole payload, so their bytes ship exactly as submitted. Restoring
111						// header newlines would inject CR bytes they never typed — into the
112						// middle of application data, since a payload holding a blank line
113						// would be misread as head+body. The textarea shows line breaks as LF
114						// and they go out as LF; exact CR bytes belong to the console's
115						// base64 editor.
116						fwd["raw"] = submitted
117					} else {
118						fwd["raw"] = ui2RestoreHeaderNewlines(submitted)
119					}
120				}
121				if msg := s.ui2ForwardTargetFields(id, r, fwd); msg != "" {
122					s.ui2InterceptRender(w, "Not forwarded: "+msg)
123					return
124				}
125				encoded, err := json.Marshal(fwd)
126				if err != nil {
127					http.Error(w, "could not encode forward request", http.StatusInternalServerError)
128					return
129				}
130				target = "/api/intercept/" + strconv.FormatUint(id, 10) + "/forward"
131				body = string(encoded)
132			} else if idText, ok := strings.CutPrefix(action, "drop-"); ok {
133				id, err := strconv.ParseUint(idText, 10, 64)
134				if err != nil {
135					http.Error(w, "unknown intercept action", http.StatusBadRequest)
136					return
137				}
138				target = "/api/intercept/" + strconv.FormatUint(id, 10) + "/drop"
139				body = `{}`
140			} else {
141				http.Error(w, "unknown intercept action", http.StatusBadRequest)
142				return
143			}
144		}
145		req := newReq(http.MethodPost, target)
146		req.Header.Set("Content-Type", "application/json")
147		req.Body = ioNopCloser(strings.NewReader(body))
148		rec := newRecorder()
149		s.mux.ServeHTTP(rec, req)
150		if rec.Code >= 400 {
151			http.Error(w, rec.Body.String(), rec.Code)
152			return
153		}
154		// Refresh the queue fragment.
155		w.Header().Set("Content-Type", "text/html; charset=utf-8")
156		_, _ = w.Write([]byte(ui2Exec("intercept.html", s.ui2InterceptView())))
157	}
