159	// handleUI2InterceptRulesToggle serves POST /ui2/intercept/rules-{direction}-{on|off}, where
160	// direction is one of requests, responses, websocket_to_server, websocket_to_client:
161	// it flips one rule list's active flag through the API, carrying the stored rules across
162	// unchanged so a toggle never rewrites the operator's list. Rule editing itself stays in the
163	// console; the page only exposes the switch.
164	func (s *Server) handleUI2InterceptRulesToggle(w http.ResponseWriter, action string) {
165		parts := strings.Split(action, "-")
166		if len(parts) != 3 || (parts[2] != "on" && parts[2] != "off") {
167			http.Error(w, "unknown intercept action", http.StatusBadRequest)
168			return
169		}
170		switch parts[1] {
171		case "requests", "responses", "websocket_to_server", "websocket_to_client":
172		default:
173			http.Error(w, "unknown intercept action", http.StatusBadRequest)
174			return
175		}
176		path := "/api/intercept/rules/" + parts[1]
177		rec := newRecorder()
178		s.mux.ServeHTTP(rec, newReq(http.MethodGet, path))
179		if rec.Code != http.StatusOK {
180			http.Error(w, "could not read the rule list", http.StatusBadGateway)
181			return
182		}
183		var state interceptListState
184		if err := ui2DecodeJSON(rec.Body.Bytes(), &state); err != nil {
185			http.Error(w, "could not decode the rule list", http.StatusBadGateway)
186			return
187		}
188		state.Active = parts[2] == "on"
189		body, err := json.Marshal(state)
190		if err != nil {
191			http.Error(w, "could not encode the rule list", http.StatusInternalServerError)
192			return
193		}
194		req := newReq(http.MethodPut, path)
195		req.Header.Set("Content-Type", "application/json")
196		req.Body = ioNopCloser(strings.NewReader(string(body)))
197		recPut := newRecorder()
198		s.mux.ServeHTTP(recPut, req)
199		if recPut.Code >= 400 {
200			http.Error(w, recPut.Body.String(), recPut.Code)
201			return
202		}
203		w.Header().Set("Content-Type", "text/html; charset=utf-8")
204		_, _ = w.Write([]byte(ui2Exec("intercept.html", s.ui2InterceptView())))
205	}
