207	// ui2NormalizeNewlines applies the same normalization an HTML textarea applies to its value:
208	// CRLF and lone CR both become LF.
209	func ui2NormalizeNewlines(s string) string {
210		return strings.NewReplacer("\r\n", "\n", "\r", "\n").Replace(s)
211	}
212	
213	// ui2RestoreHeaderNewlines undoes the textarea's normalization where the wire needs it undone.
214	// The head of an HTTP message — request or status line and headers, up to the first blank line
215	// — must be CRLF or many servers never answer, so a head that arrived pure-LF gets its endings
216	// restored. The body keeps the bytes the operator saw: textarea content round-trips LF-only
217	// content unchanged, and a submission that still has any CR came from a client that can carry
218	// them (a native form post, the console, a test) and is already byte-exact. Byte-exact editing
219	// of bodies with significant CRs stays with the console's base64 path.
220	func ui2RestoreHeaderNewlines(raw string) string {
221		if strings.ContainsRune(raw, '\r') {
222			return raw
223		}
224		head, body, found := strings.Cut(raw, "\n\n")
225		if !found {
226			// No blank line: a header-only fragment, so all of it is the head.
227			return strings.ReplaceAll(raw, "\n", "\r\n")
228		}
229		return strings.ReplaceAll(head, "\n", "\r\n") + "\r\n\r\n" + body
230	}
231	
232	// ui2HeldInfo returns the current bytes of a held message and whether it is a WebSocket
233	// message, so the per-item forward can tell an untouched round-trip from a real edit, can
234	// refuse a textarea edit of bytes the editor cannot carry, and can keep header-shaped
235	// newline restoration off payloads that have no headers. A missing hold is left for the API forward to name, which reports it as the
236	// 404 it is.
237	func (s *Server) ui2HeldInfo(id uint64) (string, bool, bool) {
238		for _, h := range s.intercept.Held() {
239			if h.ID == id {
240				return string(h.Raw), h.Direction.IsWebSocket(), true
241			}
242		}
243		return "", false, false
244	}
245	
246	// ui2TextareaSafe reports whether a held message's bytes can cross the page's raw-message
247	// editor without corruption. Two kinds cannot: bytes that are not valid UTF-8, and NULs — the
248	// HTML parser replaces a NUL in a textarea with U+FFFD exactly as it does invalid bytes, so a
249	// message that is valid UTF-8 but carries a NUL would come back from an "unchanged" round-trip
250	// with its bytes rewritten. Both kinds keep an untouched Forward and a pointer to the console's
251	// base64 editor instead of an editing surface.
252	func ui2TextareaSafe(raw []byte) bool {
253		return utf8.Valid(raw) && !bytes.Contains(raw, []byte{0})
254	}
255	
256	// ui2MarkHeldEditable flags each held view with whether the page's editor can carry it (see
257	// ui2TextareaSafe). The check reads the engine's bytes rather than the decoded view because the
258	// JSON encoding has already replaced invalid bytes with U+FFFD — itself valid UTF-8 — so the
259	// view cannot see the corruption it would pass along.
260	func (s *Server) ui2MarkHeldEditable(view map[string]any) {
261		held, ok := view["held"].([]any)
262		if !ok {
263			return
264		}
265		unsafe := map[uint64]bool{}
266		for _, h := range s.intercept.Held() {
267			unsafe[h.ID] = !ui2TextareaSafe(h.Raw)
268		}
269		for _, item := range held {
270			m, ok := item.(map[string]any)
271			if !ok {
272				continue
273			}
274			if idf, ok := m["id"].(float64); ok {
275				m["raw_editable"] = !unsafe[uint64(idf)]
276			}
277		}
278	}
