14	// ui2InterceptViewExtras adds what the full page shows beyond the queue: the newline
15	// corrections and the startup default (both read from their API rather than assumed), and per
16	// held message its URL plus, for a request, its curl command and
17	// quick-rule inputs.
18	func (s *Server) ui2InterceptViewExtras(view map[string]any) {
19		if nl, errText := s.ui2APIResult(http.MethodGet, "/api/intercept/newline-correction", nil); errText == "" {
20			view["newline"] = nl
21		}
22		if st, errText := s.ui2APIResult(http.MethodGet, "/api/intercept/startup", nil); errText == "" {
23			if m, ok := st.(map[string]any); ok {
24				view["startup_mode"] = m["mode"]
25			}
26		}
27		view["startup_persisted"] = s.persist != nil
28		held, _ := view["held"].([]any)
29		for _, item := range held {
30			m, ok := item.(map[string]any)
31			if !ok {
32				continue
33			}
34			dir, _ := m["direction"].(string)
35			host, _ := m["host"].(string)
36			path, _ := m["path"].(string)
37			raw, _ := m["raw"].(string)
38			tls, _ := m["tls"].(bool)
39			port := 0
40			if p, ok := m["port"].(float64); ok {
41				port = int(p)
42			}
43			scheme := "http"
44			if tls {
45				scheme = "https"
46			}
47			m["scheme"] = scheme
48			m["is_request"] = dir == "request"
49			m["is_response"] = dir == "response"
50			u := ui2HeldURL(scheme, host, port, path)
51			m["url"] = u
52			if dir == "request" {
53				m["curl"] = ui2RawToCurl(raw, u)
54				m["ext"] = ui2PathExtension(path)
55			}
56		}
57	}
