59	// ui2HeldURL spells a held message's URL, omitting the scheme's default port.
60	func ui2HeldURL(scheme, host string, port int, path string) string {
61		authority := host
62		if strings.Contains(host, ":") && !strings.HasPrefix(host, "[") {
63			authority = "[" + host + "]"
64		}
65		if port > 0 && !(scheme == "https" && port == 443) && !(scheme == "http" && port == 80) {
66			authority += ":" + strconv.Itoa(port)
67		}
68		return scheme + "://" + authority + path
69	}
70	
71	// ui2PathExtension is the final path segment's extension without the dot, query excluded:
72	// the value an "extension" rule is matched against.
73	func ui2PathExtension(path string) string {
74		path, _, _ = strings.Cut(path, "?")
75		if i := strings.LastIndex(path, "/"); i >= 0 {
76			path = path[i+1:]
77		}
78		if i := strings.LastIndex(path, "."); i >= 0 {
79			return path[i+1:]
80		}
81		return ""
82	}
83	
84	// ui2ShellQuote single-quotes one argument for a POSIX shell.
85	func ui2ShellQuote(v string) string {
86		return "'" + strings.ReplaceAll(v, "'", `'\''`) + "'"
87	}
88	
89	// ui2RawToCurl renders a raw request as a curl command line: method, URL, every header except
90	// Content-Length (curl computes it), and the body when there is one.
91	func ui2RawToCurl(raw, u string) string {
92		norm := strings.ReplaceAll(raw, "\r\n", "\n")
93		head, body, _ := strings.Cut(norm, "\n\n")
94		lines := strings.Split(head, "\n")
95		method := "GET"
96		if f := strings.Fields(lines[0]); len(f) > 0 {
97			method = f[0]
98		}
99		parts := []string{"curl -i -X " + ui2ShellQuote(method) + " " + ui2ShellQuote(u)}
100		for _, line := range lines[1:] {
101			name, value, ok := strings.Cut(line, ":")
102			name = strings.TrimSpace(name)
103			if !ok || name == "" || strings.EqualFold(name, "content-length") {
104				continue
105			}
106			parts = append(parts, "  -H "+ui2ShellQuote(name+": "+strings.TrimSpace(value)))
107		}
108		if strings.TrimSpace(body) != "" {
109			parts = append(parts, "  --data-raw "+ui2ShellQuote(body))
110		}
111		return strings.Join(parts, " \\\n")
112	}
