114	// ui2InterceptRender re-renders the queue fragment with an outcome note.
115	func (s *Server) ui2InterceptRender(w http.ResponseWriter, note string) {
116		view := s.ui2InterceptView()
117		view["note"] = note
118		w.Header().Set("Content-Type", "text/html; charset=utf-8")
119		_, _ = w.Write([]byte(ui2Exec("intercept.html", view)))
