122	// ui2InterceptOptionAction handles the {action} values beyond resolve/enable: the in-scope
123	// filter, newline corrections, startup default, annotation and bulk forward/drop. All are
124	// riskLocal one-click writes; each answers the re-rendered queue with a note naming the outcome
125	// or the API's refusal. It reports false for an action it does not own.
126	func (s *Server) ui2InterceptOptionAction(w http.ResponseWriter, r *http.Request, action string) bool {
127		switch {
128		case action == "in-scope-on" || action == "in-scope-off":
129			on := action == "in-scope-on"
130			if _, errText := s.ui2APIResult(http.MethodPost, "/api/intercept/in-scope-only", map[string]bool{"in_scope_only": on}); errText != "" {
131				s.ui2InterceptRender(w, "Not changed: "+errText)
132				return true
133			}
134			note := "Only in-scope messages are held now."
135			if !on {
136				note = "Messages are held whether or not they are in scope."
137			}
138			if on && !s.intercept.ScopeAttached() {
139				note += " No scope is attached, so the filter has nothing to compare against."
140			}
141			s.ui2InterceptRender(w, note)
142		case action == "newline":
143			if err := r.ParseForm(); err != nil {
144				http.Error(w, "invalid form body", http.StatusBadRequest)
145				return true
146			}
147			body := map[string]bool{
148				"add_missing_blank_line":                 r.PostForm.Get("add_missing_blank_line") == "on",
149				"trim_trailing_newlines_urlencoded_body": r.PostForm.Get("trim_trailing_newlines_urlencoded_body") == "on",
150			}
151			if _, errText := s.ui2APIResult(http.MethodPut, "/api/intercept/newline-correction", body); errText != "" {
152				s.ui2InterceptRender(w, "Not saved: "+errText)
153				return true
154			}
155			s.ui2InterceptRender(w, "Newline corrections saved; they apply to edited forwards only.")
156		case action == "startup":
157			if err := r.ParseForm(); err != nil {
158				http.Error(w, "invalid form body", http.StatusBadRequest)
159				return true
160			}
161			mode := r.PostForm.Get("mode")
162			if _, errText := s.ui2APIResult(http.MethodPost, "/api/intercept/startup", map[string]string{"mode": mode}); errText != "" {
163				s.ui2InterceptRender(w, "Not saved: "+errText)
164				return true
165			}
166			s.ui2InterceptRender(w, "Startup interception set to "+mode+"; it applies at the next server start. The live switch is unchanged.")
167		case strings.HasPrefix(action, "annotate-"):
168			id, err := strconv.ParseUint(strings.TrimPrefix(action, "annotate-"), 10, 64)
169			if err != nil {
170				http.Error(w, "unknown intercept action", http.StatusBadRequest)
171				return true
172			}
173			if err := r.ParseForm(); err != nil {
174				http.Error(w, "invalid form body", http.StatusBadRequest)
175				return true
176			}
177			highlight := r.PostForm.Get("highlight")
178			if highlight != "" && !core.ValidHighlights[highlight] {
179				s.ui2InterceptRender(w, "Not annotated: unknown highlight "+strconv.Quote(highlight))
180				return true
181			}
182			body := map[string]string{"comment": r.PostForm.Get("comment"), "highlight": highlight}
183			if _, errText := s.ui2APIResult(http.MethodPost, "/api/intercept/annotate/"+strconv.FormatUint(id, 10), body); errText != "" {
184				s.ui2InterceptRender(w, "Not annotated: "+errText)
185				return true
186			}
187			s.ui2InterceptRender(w, "Annotation saved on held #"+strconv.FormatUint(id, 10)+"; it rides into HTTP history when the message is forwarded.")
188		case action == "forward-checked" || action == "drop-checked":
189			if err := r.ParseForm(); err != nil {
190				http.Error(w, "invalid form body", http.StatusBadRequest)
191				return true
192			}
193			s.ui2InterceptRender(w, s.ui2InterceptBulk(r.PostForm["ids"], action == "forward-checked"))
194		default:
195			return false
196		}
197		return true
198	}
