200	// ui2InterceptBulk forwards or drops the checked held messages one at a time and says what
201	// happened to each. A bulk forward sends the held bytes unedited, like Forward all: one
202	// item's edit buffer never rides under another id.
203	func (s *Server) ui2InterceptBulk(ids []string, forward bool) string {
204		var ok, failed []string
205		for _, idText := range ids {
206			id, err := strconv.ParseUint(idText, 10, 64)
207			if err != nil {
208				failed = append(failed, strconv.Quote(idText))
209				continue
210			}
211			label := "#" + strconv.FormatUint(id, 10)
212			path, payload := "/api/intercept/"+strconv.FormatUint(id, 10)+"/drop", any(map[string]string{})
213			if forward {
214				path, payload = "/api/intercept/"+strconv.FormatUint(id, 10)+"/forward", map[string]bool{"fix_content_length": false}
215			}
216			if _, errText := s.ui2APIResult(http.MethodPost, path, payload); errText != "" {
217				failed = append(failed, label)
218				continue
219			}
220			ok = append(ok, label)
221		}
222		if len(ok)+len(failed) == 0 {
223			return "No held message was checked."
224		}
225		verb := "Dropped"
226		if forward {
227			verb = "Forwarded"
228		}
229		note := verb + " " + strconv.Itoa(len(ok)) + " checked message(s)"
230		if len(ok) > 0 {
231			note += " (" + strings.Join(ok, ", ") + ")"
232		}
233		if len(failed) > 0 {
234			note += "; not resolved (no longer held or refused): " + strings.Join(failed, ", ")
235		}
236		return note + "."
237	}
