239	// ui2ForwardTargetFields adds the editor's destination and hold-response choices to a forward
240	// body. The destination is sent only when it differs from where the client asked, and then as
241	// all three of host, port and tls, the API's retarget contract. Returns a refusal message for a
242	// destination that cannot be sent.
243	func (s *Server) ui2ForwardTargetFields(id uint64, r *http.Request, fwd map[string]any) string {
244		if r.PostForm.Get("hold_response") == "on" {
245			fwd["hold_response"] = true
246		}
247		_, hasHost := r.PostForm["host"]
248		_, hasPort := r.PostForm["port"]
249		_, hasScheme := r.PostForm["scheme"]
250		if !hasHost && !hasPort && !hasScheme {
251			return ""
252		}
253		if !hasHost || !hasPort || !hasScheme {
254			return "a destination needs host, port and scheme together"
255		}
256		host := strings.TrimSpace(r.PostForm.Get("host"))
257		if host == "" {
258			return "the destination host is empty"
259		}
260		port, err := strconv.ParseUint(strings.TrimSpace(r.PostForm.Get("port")), 10, 16)
261		if err != nil || port == 0 {
262			return "the destination port must be 1 to 65535"
263		}
264		scheme := r.PostForm.Get("scheme")
265		if scheme != "http" && scheme != "https" {
266			return "the destination scheme must be http or https"
267		}
268		for _, h := range s.intercept.Held() {
269			if h.ID == id && h.Host == host && h.Port == uint16(port) && h.TLS == (scheme == "https") {
270				return "" // unchanged: send it where the client asked
271			}
272		}
273		fwd["host"] = host
274		fwd["port"] = port
275		fwd["tls"] = scheme == "https"
276		return ""
277	}
278	
279	// handleUI2InterceptSend serves GET /ui2/intercept/send?id=&to=repeater|comparer|decoder: the
280	// target tool's page seeded with one held message's bytes. It reads the hold and sends
281	// nothing; the message stays held.
282	func (s *Server) handleUI2InterceptSend(w http.ResponseWriter, r *http.Request) {
283		q := r.URL.Query()
284		fail := func(msg string) {
285			ui2RenderPage(w, "burpsy /ui2/ — Intercept", "intercept", ui2Exec("error.html", ui2Error{Message: msg}))
286		}
287		id, err := strconv.ParseUint(q.Get("id"), 10, 64)
288		if err != nil {
289			fail("a held message id is required")
290			return
291		}
292		var raw, target string
293		found := false
294		for _, h := range s.intercept.Held() {
295			if h.ID != id {
296				continue
297			}
298			raw, found = string(h.Raw), true
299			scheme := "http"
300			if h.TLS {
301				scheme = "https"
302			}
303			host := h.Host
304			if strings.Contains(host, ":") {
305				host = "[" + host + "]"
306			}
307			target = scheme + "://" + host + ":" + strconv.Itoa(int(h.Port))
308		}
309		idText := strconv.FormatUint(id, 10)
310		if !found {
311			fail("held message #" + idText + " is no longer held - it was forwarded or dropped")
312			return
313		}
314		if !ui2TextareaSafe([]byte(raw)) {
315			fail("held message #" + idText + " carries bytes a text editor cannot keep unchanged (invalid UTF-8 or NUL); nothing was loaded")
316			return
317		}
318		notice := templateHTML(`<p class="meta">` + template.HTMLEscapeString("Loaded from held message #"+idText+" as an editable text copy. The message is still held on the Intercept page.") + `</p>`)
319		switch q.Get("to") {
320		case "repeater":
321			ui2RenderPage(w, "burpsy /ui2/ — Repeater", "repeater", notice+ui2Exec("repeater.html", map[string]any{"draft": raw, "target": target, "result": nil}))
322		case "comparer":
323			ui2RenderPage(w, "burpsy /ui2/ — Comparer", "comparer", notice+ui2Exec("comparer.html", map[string]any{"a": raw, "result": nil}))
324		case "decoder":
325			ui2RenderPage(w, "burpsy /ui2/ — Decoder", "decoder", notice+ui2Exec("decoder.html", map[string]any{"input": raw, "op": "decode", "arg": "", "result": nil}))
326		default:
327			fail("unknown tool: choose repeater, comparer or decoder")
328		}
329	}
