18	// ---- Intercept rules editor -------------------------------------------------------------------
19	//
20	// GET /ui2/intercept/rules?dir= renders one direction's rule list as an editable form. The
21	// editor is stateless: add, remove and reorder post the whole draft to /edit, which answers the
22	// transformed draft without writing anything. Saving is a server-held review (the PUT is
23	// riskLocal and whole-list): /confirm builds the exact PUT body from the draft, holds it with a
24	// snapshot of the list it replaces, and renders a sheet from those bytes; /run spends the entry
25	// once, re-reads the list and refuses on drift, then dispatches the held body verbatim. /quick
26	// builds the same review for Burp's "Don't intercept ..." rules from a held message.
27	//
28	// The draft carries form_base, the digest of the list the editor was opened on, so a draft made
29	// against an older list (a quick rule saved from the queue meanwhile) is refused instead of
30	// silently overwriting the newer list.
31	
32	const (
33		ui2InterceptRuleReviewCap = 8
34		ui2InterceptMaxRules      = 200
35	)
36	
37	// ui2InterceptRuleReview is one minted rule-list PUT held for review.
38	type ui2InterceptRuleReview struct {
39		token    string
40		dir      string
41		body     []byte
42		snapshot string
43		expires  time.Time
44	}
