89	func ui2InterceptFieldsFor(dir string) []ui2IRuleField {
90		d, _ := directionFor(dir)
91		out := make([]ui2IRuleField, len(ui2InterceptRuleFieldTable))
92		for i, f := range ui2InterceptRuleFieldTable {
93			parsed, err := intercept.ParseField(f.Value)
94			f.Applies = err == nil && d.HasField(parsed)
95			out[i] = f
96		}
97		return out
98	}
