137	func ui2InterceptRows(dir string, specs []interceptRuleSpec) []ui2IRuleRow {
138		d, _ := directionFor(dir)
139		rows := make([]ui2IRuleRow, len(specs))
140		for i, sp := range specs {
141			info, _ := ui2InterceptFieldInfo(sp.Field)
142			parsed, err := intercept.ParseField(sp.Field)
143			op := "or"
144			if sp.Op == "and" {
145				op = "and"
146			}
147			action := "hold"
148			if sp.Action == "pass" {
149				action = "pass"
150			}
151			rows[i] = ui2IRuleRow{
152				Index: i, Num: i + 1, Last: i == len(specs)-1, Enabled: sp.Enabled, Op: op, Action: action, Field: sp.Field, Member: sp.Member,
153				Match: sp.Match, Category: sp.Category, Comment: sp.Comment,
154				FieldLabel: info.Label, MemberLabel: info.Member, Applies: err == nil && d.HasField(parsed),
155			}
156		}
157		return rows
158	}
