160	// ui2InterceptDescribe states what a list does, including the two states that look selective
161	// and are not: an empty active list holds everything, and one with every rule unchecked holds
162	// nothing.
163	func ui2InterceptDescribe(d ui2IDir, active bool, specs []interceptRuleSpec) string {
164		if !active {
165			return "off — no " + d.Noun + " is held"
166		}
167		if len(specs) == 0 {
168			return "on with no conditions — every " + d.Noun + " is held"
169		}
170		for _, sp := range specs {
171			if sp.Enabled {
172				return fmt.Sprintf("on with %d condition(s)", len(specs))
173			}
174		}
175		return "on, but every condition is unchecked — no " + d.Noun + " is held"
176	}
