178	// ui2InterceptListRead reads one list through the API, with its canonical form for drift checks.
179	func (s *Server) ui2InterceptListRead(dir string) (interceptListState, string, error) {
180		canon, err := s.ui2CanonicalGet("/api/intercept/rules/" + dir)
181		if err != nil {
182			return interceptListState{}, "", err
183		}
184		var state interceptListState
185		if err := json.Unmarshal([]byte(canon), &state); err != nil {
186			return interceptListState{}, "", err
187		}
188		return state, canon, nil
189	}
