241	// ui2InterceptParseDraft reads the editor form: the direction, the list switch, the base
242	// digest and every indexed rule. Values outside each column's vocabulary are refused by name.
243	func ui2InterceptParseDraft(r *http.Request) (ui2IDir, bool, []interceptRuleSpec, string, string) {
244		d, ok := ui2InterceptDir(r.PostForm.Get("dir"))
245		if !ok {
246			return ui2InterceptDirs[0], false, nil, "", "unknown rule list"
247		}
248		n, err := strconv.Atoi(r.PostForm.Get("n"))
249		if err != nil || n < 0 || n > ui2InterceptMaxRules {
250			return d, false, nil, "", fmt.Sprintf("the rule count must be 0 to %d", ui2InterceptMaxRules)
251		}
252		specs := make([]interceptRuleSpec, 0, n)
253		for i := 0; i < n; i++ {
254			get := func(k string) string { return r.PostForm.Get(k + "_" + strconv.Itoa(i)) }
255			info, ok := ui2InterceptFieldInfo(get("field"))
256			if !ok {
257				return d, false, nil, "", fmt.Sprintf("rule %d: unknown match field %q", i+1, get("field"))
258			}
259			sp := interceptRuleSpec{Field: info.Value, Match: get("match"), Enabled: get("enabled") == "on", Comment: get("comment")}
260			switch get("category") {
261			case "regex", "literal":
262				sp.Category = get("category")
263			default:
264				return d, false, nil, "", fmt.Sprintf("rule %d: match kind must be regex or literal", i+1)
265			}
266			switch get("action") {
267			case "hold", "pass":
268				sp.Action = get("action")
269			default:
270				return d, false, nil, "", fmt.Sprintf("rule %d: action must be hold or pass", i+1)
271			}
272			switch get("op") {
273			case "or", "":
274			case "and":
275				sp.Op = "and"
276			default:
277				return d, false, nil, "", fmt.Sprintf("rule %d: combine must be AND or OR", i+1)
278			}
279			if info.Member != "" {
280				sp.Member = strings.TrimSpace(get("member"))
281			}
282			specs = append(specs, sp)
283		}
284		return d, r.PostForm.Get("active") == "on", specs, r.PostForm.Get("form_base"), ""
285	}
