287	// ui2InterceptValidate refuses what the PUT would refuse, before a review is minted.
288	func ui2InterceptValidate(specs []interceptRuleSpec) string {
289		if _, err := specToRules(specs); err != nil {
290			return err.Error()
291		}
292		for i, sp := range specs {
293			if sp.Category == "regex" && sp.Match != "" {
294				if _, err := regexp.Compile(sp.Match); err != nil {
295					return fmt.Sprintf("rule %d: invalid regex: %v", i+1, err)
296				}
297			}
298		}
299		return ""
300	}
