302	// handleUI2InterceptRulesAction serves POST /ui2/intercept/rules/{action}: edit (draft
303	// transforms, no write), confirm and quick (mint a review), run (spend it and save).
304	func (s *Server) handleUI2InterceptRulesAction(w http.ResponseWriter, r *http.Request) {
305		if err := r.ParseForm(); err != nil {
306			http.Error(w, "invalid form body", http.StatusBadRequest)
307			return
308		}
309		switch r.PathValue("action") {
310		case "edit", "confirm":
311			d, active, specs, base, errText := ui2InterceptParseDraft(r)
312			if errText != "" {
313				m := s.ui2InterceptRulesModel(d, active, specs, base)
314				m.Error = errText
315				ui2InterceptRulesWrite(w, r, m)
316				return
317			}
318			if r.PathValue("action") == "confirm" {
319				s.ui2InterceptRulesConfirm(w, r, d, active, specs, base)
320				return
321			}
322			specs = ui2InterceptApplyEdit(d, specs, r.PostForm.Get("edit"))
323			ui2InterceptRulesWrite(w, r, s.ui2InterceptRulesModel(d, active, specs, base))
324		case "quick":
325			s.ui2InterceptRulesQuick(w, r)
326		case "run":
327			s.ui2InterceptRulesRun(w, r)
328		default:
329			http.Error(w, "unknown intercept rules action", http.StatusBadRequest)
330		}
331	}
332	
333	// ui2InterceptApplyEdit applies one draft transform: add, up-N, down-N or delete-N. Anything
334	// else re-renders the draft unchanged.
335	func ui2InterceptApplyEdit(d ui2IDir, specs []interceptRuleSpec, edit string) []interceptRuleSpec {
336		if edit == "add" {
337			if len(specs) >= ui2InterceptMaxRules {
338				return specs
339			}
340			return append(specs, interceptRuleSpec{Field: d.DefaultField, Category: "regex", Enabled: true, Action: "hold"})
341		}
342		verb, idxText, ok := strings.Cut(edit, "-")
343		i, err := strconv.Atoi(idxText)
344		if !ok || err != nil || i < 0 || i >= len(specs) {
345			return specs
346		}
347		switch verb {
348		case "up":
349			if i > 0 {
350				specs[i-1], specs[i] = specs[i], specs[i-1]
351			}
352		case "down":
353			if i < len(specs)-1 {
354				specs[i], specs[i+1] = specs[i+1], specs[i]
355			}
356		case "delete":
357			specs = append(specs[:i], specs[i+1:]...)
358		}
359		return specs
360	}
361	
362	func (s *Server) ui2InterceptRulesConfirm(w http.ResponseWriter, r *http.Request, d ui2IDir, active bool, specs []interceptRuleSpec, base string) {
363		refuse := func(msg string) {
364			m := s.ui2InterceptRulesModel(d, active, specs, base)
365			m.Error = msg
366			ui2InterceptRulesWrite(w, r, m)
367		}
368		before, canon, err := s.ui2InterceptListRead(d.Name)
369		if err != nil {
370			refuse("could not read the current list: " + err.Error())
371			return
372		}
373		if subtle.ConstantTimeCompare([]byte(base), []byte(ui2InterceptDigest(canon))) != 1 {
374			refuse("the " + d.Noun + " list changed since this editor opened - reload it (your draft is still shown here) and redo the edit, so the save cannot overwrite the newer rules")
375			return
376		}
377		s.ui2InterceptRulesMint(w, r, d, before, canon, active, specs, refuse, nil)
378	}
379	
380	// ui2InterceptRulesMint validates the new list, holds the exact PUT and renders the sheet.
381	func (s *Server) ui2InterceptRulesMint(w http.ResponseWriter, r *http.Request, d ui2IDir, before interceptListState, canon string, active bool, specs []interceptRuleSpec, refuse func(string), extra []string) {
382		if msg := ui2InterceptValidate(specs); msg != "" {
383			refuse("not reviewable: " + msg)
384			return
385		}
386		if specs == nil {
387			specs = []interceptRuleSpec{}
388		}
389		type putBody struct {
390			Active bool                `json:"active"`
391			Rules  []interceptRuleSpec `json:"rules"`
392		}
393		body, err := json.Marshal(putBody{Active: active, Rules: specs})
394		if err != nil {
395			refuse("could not encode the list")
396			return
397		}
398		beforeRules := before.Rules
399		if beforeRules == nil {
400			beforeRules = []interceptRuleSpec{}
401		}
402		if cur, _ := json.Marshal(putBody{Active: before.Active, Rules: beforeRules}); string(cur) == string(body) {
403			refuse("the draft is the same as the stored list - nothing to save")
404			return
405		}
406		now := time.Now()
407		count := 0
408		s.ui2InterceptRuleReviews.Range(func(k, v any) bool {
409			if e, ok := v.(ui2InterceptRuleReview); ok && now.After(e.expires) {
410				s.ui2InterceptRuleReviews.Delete(k)
411			} else {
412				count++
413			}
414			return true
415		})
416		if count >= ui2InterceptRuleReviewCap {
417			refuse("too many rule reviews are open at once - confirm or let some expire, then try again")
418			return
419		}
420		token, err1 := randomHex(16)
421		id, err2 := randomHex(16)
422		if err1 != nil || err2 != nil {
423			refuse("could not create a review")
424			return
425		}
426		s.ui2InterceptRuleReviews.Store(id, ui2InterceptRuleReview{token: token, dir: d.Name, body: body, snapshot: canon, expires: now.Add(ConfirmTTL)})
427	
428		// The sheet is derived from the held bytes, not from the form.
429		var held putBody
430		_ = json.Unmarshal(body, &held)
431		pretty, _ := json.MarshalIndent(held, "", "  ")
432		consequences := append([]string{
433			fmt.Sprintf("Replaces the whole %s list: %d rule(s) stored now, %d after this save.", d.Noun, len(before.Rules), len(held.Rules)),
434			"After saving, the list is " + ui2InterceptDescribe(d, held.Active, held.Rules) + ".",
435		}, extra...)
436		if before.Active && len(before.Rules) == 0 && len(held.Rules) > 0 {
437			consequences = append(consequences, "The list currently holds every "+d.Noun+"; after this save it holds only what its enabled rules select.")
438		}
439		for _, row := range ui2InterceptRows(d.Name, held.Rules) {
440			if !row.Applies {
441				consequences = append(consequences, fmt.Sprintf("Rule %d matches %s, which a %s never carries, so it can never match.", row.Index+1, row.FieldLabel, d.Noun))
442			}
443		}
444		consequences = append(consequences,
445			"Nothing is sent and no held message is resolved; the rules decide what is held from now on.",
446			"Saving re-reads the list and refuses if it changed since this review. That is a check, not a lock.")
447		m := ui2IRulesModel{
448			Dir: d, Dirs: ui2InterceptDirs, Active: held.Active, Rules: ui2InterceptRows(d.Name, held.Rules),
449			Review: true, Call: "PUT /api/intercept/rules/" + d.Name + "\n" + string(pretty),
450			Consequences: consequences, ReviewID: id, Token: token,
451		}
452		ui2InterceptRulesWrite(w, r, m)
453	}
