455	// ui2InterceptRulesQuick builds Burp's quick rules from a held message: don't intercept
456	// requests to this host or for this extension, or responses from this host. The pass rule goes
457	// at the TOP of the list: below a broader hold rule it would never be reached.
458	func (s *Server) ui2InterceptRulesQuick(w http.ResponseWriter, r *http.Request) {
459		fail := func(d ui2IDir, msg string) {
460			ui2InterceptRulesWrite(w, r, ui2IRulesModel{Dir: d, Dirs: ui2InterceptDirs, Error: msg})
461		}
462		id, err := strconv.ParseUint(r.PostForm.Get("id"), 10, 64)
463		if err != nil {
464			fail(ui2InterceptDirs[0], "a held message id is required")
465			return
466		}
467		var h *intercept.Held
468		for _, x := range s.intercept.Held() {
469			if x.ID == id {
470				h = x
471			}
472		}
473		if h == nil {
474			fail(ui2InterceptDirs[0], fmt.Sprintf("held message #%d is no longer held - it was forwarded or dropped", id))
475			return
476		}
477		var dirName, field, match, what string
478		switch kind := r.PostForm.Get("kind"); {
479		case kind == "pass-host" && h.Direction == intercept.DirectionRequest:
480			dirName, field, match, what = "requests", "host", h.Host, "requests to "+h.Host
481		case kind == "pass-ext" && h.Direction == intercept.DirectionRequest && ui2PathExtension(h.Path) != "":
482			ext := ui2PathExtension(h.Path)
483			dirName, field, match, what = "requests", "extension", ext, "requests for ."+ext+" files"
484		case kind == "pass-host" && h.Direction == intercept.DirectionResponse:
485			dirName, field, match, what = "responses", "host", h.Host, "responses from "+h.Host
486		default:
487			fail(ui2InterceptDirs[0], "that quick rule does not apply to this held message")
488			return
489		}
490		d, _ := ui2InterceptDir(dirName)
491		before, canon, err := s.ui2InterceptListRead(d.Name)
492		if err != nil {
493			fail(d, "could not read the current list: "+err.Error())
494			return
495		}
496		rule := interceptRuleSpec{Field: field, Category: "literal", Match: match, Enabled: true, Action: "pass", Comment: fmt.Sprintf("from held #%d", id)}
497		specs := append([]interceptRuleSpec{rule}, before.Rules...)
498		s.ui2InterceptRulesMint(w, r, d, before, canon, before.Active, specs, func(msg string) { fail(d, msg) },
499			[]string{"Adds a Don't intercept rule at the top of the list: " + what + " will no longer be held. Held message #" + strconv.FormatUint(id, 10) + " itself stays held."})
500	}
501	
502	func (s *Server) ui2InterceptRulesRun(w http.ResponseWriter, r *http.Request) {
503		fail := func(d ui2IDir, msg string) {
504			ui2InterceptRulesWrite(w, r, ui2IRulesModel{Dir: d, Dirs: ui2InterceptDirs, Error: msg})
505		}
506		v, ok := s.ui2InterceptRuleReviews.LoadAndDelete(r.PostForm.Get("review_id"))
507		entry, isReview := v.(ui2InterceptRuleReview)
508		if !ok || !isReview {
509			fail(ui2InterceptDirs[0], "that review is unknown or was already used - review the change again")
510			return
511		}
512		d, _ := ui2InterceptDir(entry.dir)
513		if time.Now().After(entry.expires) {
514			fail(d, "that review expired with the confirmation window - review the change again")
515			return
516		}
517		if subtle.ConstantTimeCompare([]byte(entry.token), []byte(r.PostForm.Get("token"))) != 1 {
518			fail(d, "that review does not match this confirmation - review the change again")
519			return
520		}
521		if _, canon, err := s.ui2InterceptListRead(d.Name); err != nil || canon != entry.snapshot {
522			fail(d, "the "+d.Noun+" list changed since this review - nothing was saved; reload and review again")
523			return
524		}
525		req := newReq(http.MethodPut, "/api/intercept/rules/"+d.Name)
526		req.Header.Set("Content-Type", "application/json")
527		req.Body = ioNopCloser(strings.NewReader(string(entry.body)))
528		rec := newRecorder()
529		s.mux.ServeHTTP(rec, req)
530		if rec.Code != http.StatusOK {
531			fail(d, "the rules API refused the list: "+truncateForDisplay(strings.TrimSpace(rec.Body.String()), 200))
532			return
533		}
